CREATE TABLE longitudinal_cases(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),cycle_id TEXT NOT NULL,cycle_version INTEGER NOT NULL,initial_owner_id TEXT NOT NULL REFERENCES users(id),serial INTEGER NOT NULL,case_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(id,store_id,customer_id),FOREIGN KEY(cycle_id,cycle_version) REFERENCES cycle_versions(cycle_id,version));
CREATE TABLE longitudinal_case_versions(case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),title TEXT NOT NULL,baseline_note TEXT NOT NULL,goal_note TEXT NOT NULL,source_note TEXT NOT NULL,manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(case_id,version),FOREIGN KEY(case_id,store_id,customer_id) REFERENCES longitudinal_cases(id,store_id,customer_id));
CREATE TABLE longitudinal_case_events(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,revision INTEGER NOT NULL,sequence INTEGER NOT NULL,version INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('create','revise','activate','pause','resume','transfer','close')),status TEXT NOT NULL CHECK(status IN('draft','active','paused','closed')),owner_id TEXT NOT NULL REFERENCES users(id),close_reason TEXT,next_step TEXT,followup_task_id TEXT REFERENCES work_tasks(id),followup_revision INTEGER,note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(case_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(case_id,store_id,customer_id) REFERENCES longitudinal_cases(id,store_id,customer_id),FOREIGN KEY(case_id,version) REFERENCES longitudinal_case_versions(case_id,version),CHECK((followup_task_id IS NULL AND followup_revision IS NULL) OR(followup_task_id IS NOT NULL AND followup_revision IS NOT NULL)),CHECK((status='closed' AND close_reason IS NOT NULL AND next_step IS NOT NULL) OR(status!='closed' AND close_reason IS NULL AND next_step IS NULL AND followup_task_id IS NULL)));
CREATE TABLE longitudinal_observations(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,initial_case_revision INTEGER NOT NULL,serial INTEGER NOT NULL,observation_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(id,case_id,store_id,customer_id),FOREIGN KEY(case_id,store_id,customer_id) REFERENCES longitudinal_cases(id,store_id,customer_id),FOREIGN KEY(case_id,initial_case_revision) REFERENCES longitudinal_case_events(case_id,revision));
CREATE TABLE longitudinal_observation_versions(observation_id TEXT NOT NULL,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,version INTEGER NOT NULL,sequence INTEGER NOT NULL,case_revision INTEGER NOT NULL,measured_at TEXT NOT NULL,eye TEXT NOT NULL CHECK(eye IN('right','left','both','not_specified')),condition_status TEXT NOT NULL CHECK(condition_status IN('recorded','unknown','incomparable')),condition_note TEXT NOT NULL,source TEXT NOT NULL CHECK(source IN('staff_record','external_transcript','guardian_transcript')),source_note TEXT NOT NULL,record_note TEXT NOT NULL,manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(observation_id,version),UNIQUE(store_id,sequence),FOREIGN KEY(observation_id,case_id,store_id,customer_id) REFERENCES longitudinal_observations(id,case_id,store_id,customer_id),FOREIGN KEY(case_id,case_revision) REFERENCES longitudinal_case_events(case_id,revision));
CREATE TABLE review_plans(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,initial_case_revision INTEGER NOT NULL,initial_case_version INTEGER NOT NULL,serial INTEGER NOT NULL,plan_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(id,case_id,store_id,customer_id),FOREIGN KEY(case_id,store_id,customer_id) REFERENCES longitudinal_cases(id,store_id,customer_id),FOREIGN KEY(case_id,initial_case_revision) REFERENCES longitudinal_case_events(case_id,revision),FOREIGN KEY(case_id,initial_case_version) REFERENCES longitudinal_case_versions(case_id,version));
CREATE TABLE review_plan_events(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,revision INTEGER NOT NULL,sequence INTEGER NOT NULL,case_revision INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('create','revise','pause','resume','assign','cancel','complete')),status TEXT NOT NULL CHECK(status IN('scheduled','paused','completed','cancelled')),due_date TEXT NOT NULL CHECK(length(due_date)=10 AND date(due_date,'+0 days') IS due_date),purpose TEXT NOT NULL,items_note TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),source_note TEXT NOT NULL,manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),completed_at TEXT,resolution_note TEXT,next_step TEXT,note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(plan_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(plan_id,case_id,store_id,customer_id) REFERENCES review_plans(id,case_id,store_id,customer_id),FOREIGN KEY(case_id,case_revision) REFERENCES longitudinal_case_events(case_id,revision),CHECK((status='completed' AND completed_at IS NOT NULL AND resolution_note IS NOT NULL AND next_step IS NOT NULL) OR(status='cancelled' AND completed_at IS NULL AND resolution_note IS NOT NULL AND next_step IS NOT NULL) OR(status IN('scheduled','paused') AND completed_at IS NULL AND resolution_note IS NULL AND next_step IS NULL)));
CREATE VIEW longitudinal_journal AS SELECT store_id,sequence,created_at,'case' kind,case_id root_id,id FROM longitudinal_case_events UNION ALL SELECT store_id,sequence,created_at,'observation',observation_id,observation_id||':'||version FROM longitudinal_observation_versions UNION ALL SELECT store_id,sequence,created_at,'plan',plan_id,id FROM review_plan_events;
CREATE VIEW longitudinal_case_current AS SELECT * FROM longitudinal_case_events e WHERE revision=(SELECT max(revision) FROM longitudinal_case_events WHERE case_id=e.case_id);
CREATE VIEW longitudinal_observation_current AS SELECT * FROM longitudinal_observation_versions e WHERE version=(SELECT max(version) FROM longitudinal_observation_versions WHERE observation_id=e.observation_id);
CREATE VIEW review_plan_current AS SELECT * FROM review_plan_events e WHERE revision=(SELECT max(revision) FROM review_plan_events WHERE plan_id=e.plan_id);
CREATE INDEX longitudinal_customer ON longitudinal_cases(customer_id,serial);
CREATE INDEX longitudinal_observation_date ON longitudinal_observation_versions(customer_id,measured_at);
CREATE INDEX review_due_date ON review_plan_events(store_id,due_date);

CREATE TRIGGER longitudinal_cases_no_update BEFORE UPDATE ON longitudinal_cases BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER longitudinal_cases_no_delete BEFORE DELETE ON longitudinal_cases BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER longitudinal_cases_actor BEFORE INSERT ON longitudinal_cases WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND coalesce(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'longitudinal actor/time mismatch'); END;

CREATE TRIGGER longitudinal_case_versions_no_update BEFORE UPDATE ON longitudinal_case_versions BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER longitudinal_case_versions_no_delete BEFORE DELETE ON longitudinal_case_versions BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER longitudinal_case_versions_actor BEFORE INSERT ON longitudinal_case_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND coalesce(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'longitudinal actor/time mismatch'); END;

CREATE TRIGGER longitudinal_case_events_no_update BEFORE UPDATE ON longitudinal_case_events BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER longitudinal_case_events_no_delete BEFORE DELETE ON longitudinal_case_events BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER longitudinal_case_events_actor BEFORE INSERT ON longitudinal_case_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('manager','professional') AND coalesce(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'longitudinal actor/time mismatch'); END;

CREATE TRIGGER longitudinal_observations_no_update BEFORE UPDATE ON longitudinal_observations BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER longitudinal_observations_no_delete BEFORE DELETE ON longitudinal_observations BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER longitudinal_observations_actor BEFORE INSERT ON longitudinal_observations WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND coalesce(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'longitudinal actor/time mismatch'); END;

CREATE TRIGGER longitudinal_observation_versions_no_update BEFORE UPDATE ON longitudinal_observation_versions BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER longitudinal_observation_versions_no_delete BEFORE DELETE ON longitudinal_observation_versions BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER longitudinal_observation_versions_actor BEFORE INSERT ON longitudinal_observation_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND coalesce(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'longitudinal actor/time mismatch'); END;

CREATE TRIGGER review_plans_no_update BEFORE UPDATE ON review_plans BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER review_plans_no_delete BEFORE DELETE ON review_plans BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER review_plans_actor BEFORE INSERT ON review_plans WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND coalesce(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'longitudinal actor/time mismatch'); END;

CREATE TRIGGER review_plan_events_no_update BEFORE UPDATE ON review_plan_events BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER review_plan_events_no_delete BEFORE DELETE ON review_plan_events BEGIN SELECT RAISE(ABORT,'immutable longitudinal history'); END;

CREATE TRIGGER review_plan_events_actor BEFORE INSERT ON review_plan_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('manager','professional') AND coalesce(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'longitudinal actor/time mismatch'); END;

CREATE TRIGGER longitudinal_cases_number BEFORE INSERT ON longitudinal_cases WHEN NEW.serial!=(SELECT coalesce(max(serial),0)+1 FROM longitudinal_cases WHERE store_id=NEW.store_id) OR NEW.case_number!=('LC-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial)) BEGIN SELECT RAISE(ABORT,'longitudinal number mismatch'); END;

CREATE TRIGGER longitudinal_observations_number BEFORE INSERT ON longitudinal_observations WHEN NEW.serial!=(SELECT coalesce(max(serial),0)+1 FROM longitudinal_observations WHERE store_id=NEW.store_id) OR NEW.observation_number!=('LO-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial)) BEGIN SELECT RAISE(ABORT,'longitudinal number mismatch'); END;

CREATE TRIGGER review_plans_number BEFORE INSERT ON review_plans WHEN NEW.serial!=(SELECT coalesce(max(serial),0)+1 FROM review_plans WHERE store_id=NEW.store_id) OR NEW.plan_number!=('RP-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial)) BEGIN SELECT RAISE(ABORT,'longitudinal number mismatch'); END;

CREATE TRIGGER longitudinal_case_events_sequence BEFORE INSERT ON longitudinal_case_events WHEN NEW.sequence!=(SELECT coalesce(max(sequence),0)+1 FROM longitudinal_journal WHERE store_id=NEW.store_id) OR NEW.created_at<coalesce((SELECT max(created_at) FROM longitudinal_journal WHERE store_id=NEW.store_id),NEW.created_at) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) BEGIN SELECT RAISE(ABORT,'longitudinal journal mismatch'); END;

CREATE TRIGGER longitudinal_observation_versions_sequence BEFORE INSERT ON longitudinal_observation_versions WHEN NEW.sequence!=(SELECT coalesce(max(sequence),0)+1 FROM longitudinal_journal WHERE store_id=NEW.store_id) OR NEW.created_at<coalesce((SELECT max(created_at) FROM longitudinal_journal WHERE store_id=NEW.store_id),NEW.created_at) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) BEGIN SELECT RAISE(ABORT,'longitudinal journal mismatch'); END;

CREATE TRIGGER review_plan_events_sequence BEFORE INSERT ON review_plan_events WHEN NEW.sequence!=(SELECT coalesce(max(sequence),0)+1 FROM longitudinal_journal WHERE store_id=NEW.store_id) OR NEW.created_at<coalesce((SELECT max(created_at) FROM longitudinal_journal WHERE store_id=NEW.store_id),NEW.created_at) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) BEGIN SELECT RAISE(ABORT,'longitudinal journal mismatch'); END;

CREATE TRIGGER longitudinal_case_root BEFORE INSERT ON longitudinal_cases WHEN NEW.initial_owner_id!=NEW.created_by OR NOT EXISTS(SELECT 1 FROM cycle_versions v JOIN customers c ON c.id=v.customer_id WHERE v.cycle_id=NEW.cycle_id AND v.version=NEW.cycle_version AND v.version=(SELECT max(version) FROM cycle_versions WHERE cycle_id=NEW.cycle_id) AND v.type='followup' AND v.customer_id=NEW.customer_id AND c.store_id=NEW.store_id AND v.created_at<=NEW.created_at) BEGIN SELECT RAISE(ABORT,'longitudinal fixed demand mismatch'); END;

CREATE TRIGGER longitudinal_case_version_guard BEFORE INSERT ON longitudinal_case_versions WHEN NEW.version!=(SELECT coalesce(max(version),0)+1 FROM longitudinal_case_versions WHERE case_id=NEW.case_id) OR NEW.base_sequence!=(SELECT coalesce(max(sequence),0) FROM longitudinal_journal WHERE store_id=NEW.store_id) OR (length(trim(NEW.title)) NOT BETWEEN 1 AND 120 OR length(NEW.title)>120) OR (length(trim(NEW.baseline_note)) NOT BETWEEN 1 AND 3000 OR length(NEW.baseline_note)>3000) OR (length(trim(NEW.goal_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.goal_note)>1000) OR (length(trim(NEW.source_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_note)>1000) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) OR (NEW.version=1 AND NOT EXISTS(SELECT 1 FROM longitudinal_cases WHERE id=NEW.case_id AND initial_owner_id=NEW.created_by AND created_at=NEW.created_at)) OR (NEW.version>1 AND NOT EXISTS(SELECT 1 FROM longitudinal_case_current WHERE case_id=NEW.case_id AND owner_id=NEW.created_by AND status!='closed')) BEGIN SELECT RAISE(ABORT,'longitudinal draft version mismatch'); END;

CREATE TRIGGER longitudinal_case_event_guard BEFORE INSERT ON longitudinal_case_events WHEN NEW.revision!=(SELECT coalesce(max(revision),0)+1 FROM longitudinal_case_events WHERE case_id=NEW.case_id) OR NEW.version!=(SELECT max(version) FROM longitudinal_case_versions WHERE case_id=NEW.case_id) OR (length(trim(NEW.note)) NOT BETWEEN 1 AND 1000 OR length(NEW.note)>1000) OR (NEW.revision=1 AND NOT EXISTS(SELECT 1 FROM longitudinal_cases r WHERE r.id=NEW.case_id AND NEW.action='create' AND NEW.status='draft' AND NEW.version=1 AND NEW.owner_id=r.initial_owner_id AND NEW.created_by=r.created_by AND NEW.created_at=r.created_at)) OR (NEW.action IN('create','revise') AND NOT EXISTS(SELECT 1 FROM longitudinal_case_versions v WHERE v.case_id=NEW.case_id AND v.version=NEW.version AND v.base_sequence=NEW.sequence-1 AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by)) OR (NEW.revision>1 AND NOT EXISTS(SELECT 1 FROM longitudinal_case_current p WHERE p.case_id=NEW.case_id AND p.status!='closed' AND ((NEW.action='revise' AND NEW.version=p.version+1 AND NEW.status=p.status AND NEW.owner_id=p.owner_id) OR (NEW.action='activate' AND p.status='draft' AND NEW.status='active' AND NEW.version=p.version AND NEW.owner_id=p.owner_id) OR(NEW.action='pause' AND p.status='active' AND NEW.status='paused' AND NEW.version=p.version AND NEW.owner_id=p.owner_id) OR(NEW.action='resume' AND p.status='paused' AND NEW.status='active' AND NEW.version=p.version AND NEW.owner_id=p.owner_id) OR(NEW.action='transfer' AND NEW.status=p.status AND NEW.owner_id!=p.owner_id AND NEW.version=p.version) OR(NEW.action='close' AND NEW.status='closed' AND NEW.owner_id=p.owner_id AND NEW.version=p.version)) AND (NEW.created_by=p.owner_id OR NEW.action IN('pause','transfer','close') AND (SELECT role FROM users WHERE id=NEW.created_by)='manager'))) OR (NEW.action IN('create','activate','resume','revise') AND (SELECT role FROM users WHERE id=NEW.created_by)!='professional') OR (NEW.action='transfer' AND NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.owner_id AND u.store_id=NEW.store_id AND u.role='professional' AND u.active=1 AND coalesce(x.must_change_password,0)=0)) BEGIN SELECT RAISE(ABORT,'longitudinal case transition mismatch'); END;

CREATE TRIGGER longitudinal_case_close_guard BEFORE INSERT ON longitudinal_case_events WHEN NEW.action='close' AND ((length(trim(NEW.close_reason)) NOT BETWEEN 1 AND 1000 OR length(NEW.close_reason)>1000) OR (length(trim(NEW.next_step)) NOT BETWEEN 1 AND 1000 OR length(NEW.next_step)>1000) OR EXISTS(SELECT 1 FROM review_plans p JOIN review_plan_current e ON e.plan_id=p.id WHERE p.case_id=NEW.case_id AND e.status IN('scheduled','paused')) OR(NEW.followup_task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM work_tasks t JOIN longitudinal_cases c ON c.id=NEW.case_id WHERE t.id=NEW.followup_task_id AND t.revision=NEW.followup_revision AND t.customer_id=c.customer_id AND t.store_id=c.store_id AND t.cycle_id=c.cycle_id AND t.lifecycle_status='active' AND NOT EXISTS(SELECT 1 FROM task_completions WHERE task_id=t.id)))) BEGIN SELECT RAISE(ABORT,'longitudinal unresolved plan or closure mismatch'); END;

CREATE TRIGGER longitudinal_observations_case_guard BEFORE INSERT ON longitudinal_observations WHEN NOT EXISTS(SELECT 1 FROM longitudinal_case_current e WHERE e.case_id=NEW.case_id AND e.revision=NEW.initial_case_revision AND e.owner_id=NEW.created_by AND e.status IN('active','paused') AND e.created_at<=NEW.created_at) BEGIN SELECT RAISE(ABORT,'longitudinal current case mismatch'); END;

CREATE TRIGGER review_plans_case_guard BEFORE INSERT ON review_plans WHEN NOT EXISTS(SELECT 1 FROM longitudinal_case_current e WHERE e.case_id=NEW.case_id AND e.revision=NEW.initial_case_revision AND e.owner_id=NEW.created_by AND e.status IN('active') AND e.created_at<=NEW.created_at AND e.version=NEW.initial_case_version) BEGIN SELECT RAISE(ABORT,'longitudinal current case mismatch'); END;

CREATE TRIGGER longitudinal_observation_version_guard BEFORE INSERT ON longitudinal_observation_versions WHEN NEW.version!=(SELECT coalesce(max(version),0)+1 FROM longitudinal_observation_versions WHERE observation_id=NEW.observation_id) OR NOT EXISTS(SELECT 1 FROM longitudinal_case_current c WHERE c.case_id=NEW.case_id AND c.revision=NEW.case_revision AND c.owner_id=NEW.created_by AND c.status IN('active','paused')) OR (NEW.version=1 AND NOT EXISTS(SELECT 1 FROM longitudinal_observations r WHERE r.id=NEW.observation_id AND r.created_by=NEW.created_by AND r.created_at=NEW.created_at AND r.initial_case_revision=NEW.case_revision)) OR length(NEW.measured_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.measured_at) IS NOT NEW.measured_at OR NEW.measured_at>NEW.created_at OR (length(trim(NEW.condition_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.condition_note)>1000) OR (length(trim(NEW.source_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_note)>1000) OR (length(trim(NEW.record_note)) NOT BETWEEN 1 AND 3000 OR length(NEW.record_note)>3000) BEGIN SELECT RAISE(ABORT,'longitudinal observation mismatch'); END;

CREATE TRIGGER review_plan_event_guard BEFORE INSERT ON review_plan_events WHEN NEW.revision!=(SELECT coalesce(max(revision),0)+1 FROM review_plan_events WHERE plan_id=NEW.plan_id) OR NOT EXISTS(SELECT 1 FROM longitudinal_case_current c WHERE c.case_id=NEW.case_id AND c.revision=NEW.case_revision AND c.status IN('active','paused')) OR (length(trim(NEW.purpose)) NOT BETWEEN 1 AND 300 OR length(NEW.purpose)>300) OR (length(trim(NEW.items_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.items_note)>2000) OR (length(trim(NEW.source_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_note)>1000) OR (length(trim(NEW.note)) NOT BETWEEN 1 AND 1000 OR length(NEW.note)>1000) OR (NEW.action IN('create','revise','resume') AND NOT EXISTS(SELECT 1 FROM longitudinal_case_current c WHERE c.case_id=NEW.case_id AND c.status='active')) OR (NEW.action IN('create','revise','resume','complete') AND (SELECT role FROM users WHERE id=NEW.created_by)!='professional') OR (NEW.revision=1 AND NOT EXISTS(SELECT 1 FROM review_plans r JOIN longitudinal_case_current c ON c.case_id=r.case_id WHERE r.id=NEW.plan_id AND NEW.action='create' AND NEW.status='scheduled' AND r.created_at=NEW.created_at AND r.created_by=NEW.created_by AND c.owner_id=NEW.created_by AND r.initial_case_revision=NEW.case_revision)) OR (NEW.revision>1 AND NOT EXISTS(SELECT 1 FROM review_plan_current p JOIN longitudinal_case_current c ON c.case_id=p.case_id WHERE p.plan_id=NEW.plan_id AND p.status IN('scheduled','paused') AND ((NEW.action='revise' AND NEW.status=p.status) OR (NEW.action='pause' AND p.status='scheduled' AND NEW.status='paused') OR(NEW.action='resume' AND p.status='paused' AND NEW.status='scheduled') OR(NEW.action='assign' AND NEW.status=p.status AND NEW.owner_id!=p.owner_id) OR(NEW.action='cancel' AND NEW.status='cancelled') OR(NEW.action='complete' AND NEW.status='completed')) AND (NEW.created_by=p.owner_id OR NEW.created_by=c.owner_id OR NEW.action IN('pause','assign','cancel') AND (SELECT role FROM users WHERE id=NEW.created_by)='manager'))) OR(NEW.action IN('pause','resume','assign','cancel','complete') AND EXISTS(SELECT 1 FROM review_plan_current p WHERE p.plan_id=NEW.plan_id AND (NEW.due_date!=p.due_date OR NEW.purpose!=p.purpose OR NEW.items_note!=p.items_note OR NEW.source_note!=p.source_note OR(NEW.action!='assign' AND NEW.owner_id!=p.owner_id) OR(NEW.action NOT IN('cancel','complete') AND NEW.manifest_json!=p.manifest_json)))) OR(NEW.action IN('create','revise','assign','resume','complete') AND NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.owner_id AND u.role='professional' AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(x.must_change_password,0)=0)) OR(NEW.action IN('cancel','complete') AND ((length(trim(NEW.resolution_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.resolution_note)>1000) OR (length(trim(NEW.next_step)) NOT BETWEEN 1 AND 1000 OR length(NEW.next_step)>1000))) OR(NEW.action='complete' AND (length(NEW.completed_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.completed_at) IS NOT NEW.completed_at OR NEW.completed_at>NEW.created_at OR json_array_length(NEW.manifest_json,'$.observations')<1 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.observations') j JOIN longitudinal_observation_versions v ON v.observation_id=json_extract(j.value,'$.id') AND v.version=json_extract(j.value,'$.version') WHERE v.measured_at>NEW.completed_at))) BEGIN SELECT RAISE(ABORT,'review plan transition/source mismatch'); END;

CREATE TRIGGER longitudinal_case_versions_manifest_shape BEFORE INSERT ON longitudinal_case_versions WHEN json_type(NEW.manifest_json) IS NOT 'object' OR (SELECT count(*) FROM json_each(NEW.manifest_json))!=4 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json) WHERE key NOT IN('documents','reassessments','observations','followup')) OR json_type(NEW.manifest_json,'$.observations') IS NOT 'array' OR json_array_length(NEW.manifest_json,'$.observations')>30 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.observations') j WHERE j.type!='object' OR (SELECT count(*) FROM json_each(j.value))!=2 OR json_type(j.value,'$.id') IS NOT 'text' OR length(json_extract(j.value,'$.id')) NOT BETWEEN 1 AND 100 OR EXISTS(SELECT 1 FROM json_each(j.value) WHERE key NOT IN('id','version')) OR json_type(j.value,'$.version') IS NOT 'integer' OR json_extract(j.value,'$.version') NOT BETWEEN 1 AND 1000000000) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.observations') GROUP BY json_extract(value,'$.id') HAVING count(*)>1) OR json_type(NEW.manifest_json,'$.reassessments') IS NOT 'array' OR json_array_length(NEW.manifest_json,'$.reassessments')>30 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.reassessments') j WHERE j.type!='object' OR (SELECT count(*) FROM json_each(j.value))!=3 OR json_type(j.value,'$.id') IS NOT 'text' OR length(json_extract(j.value,'$.id')) NOT BETWEEN 1 AND 100 OR EXISTS(SELECT 1 FROM json_each(j.value) WHERE key NOT IN('id','version','revision')) OR json_type(j.value,'$.version') IS NOT 'integer' OR json_extract(j.value,'$.version') NOT BETWEEN 1 AND 1000000000 OR json_type(j.value,'$.revision') IS NOT 'integer' OR json_extract(j.value,'$.revision') NOT BETWEEN 1 AND 1000000000) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.reassessments') GROUP BY json_extract(value,'$.id') HAVING count(*)>1) OR json_type(NEW.manifest_json,'$.documents') IS NOT 'array' OR json_array_length(NEW.manifest_json,'$.documents')>30 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.documents') WHERE type!='text' OR length(value) NOT BETWEEN 1 AND 100) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.documents') GROUP BY value HAVING count(*)>1) OR json_type(NEW.manifest_json,'$.followup') IS NULL OR json_type(NEW.manifest_json,'$.followup') NOT IN('null','object') OR(json_type(NEW.manifest_json,'$.followup')='object' AND ((SELECT count(*) FROM json_each(NEW.manifest_json,'$.followup'))!=2 OR json_type(NEW.manifest_json,'$.followup.id') IS NOT 'text' OR length(json_extract(NEW.manifest_json,'$.followup.id')) NOT BETWEEN 1 AND 100 OR json_type(NEW.manifest_json,'$.followup.revision') IS NOT 'integer' OR json_extract(NEW.manifest_json,'$.followup.revision') NOT BETWEEN 1 AND 1000000000 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.followup') WHERE key NOT IN('id','revision')))) OR json_type(NEW.manifest_json,'$.followup') IS NOT 'null' BEGIN SELECT RAISE(ABORT,'longitudinal manifest shape mismatch'); END;

CREATE TRIGGER longitudinal_case_versions_manifest_source BEFORE INSERT ON longitudinal_case_versions WHEN EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.documents') j WHERE NOT EXISTS(SELECT 1 FROM document_versions d WHERE d.id=j.value AND d.customer_id=NEW.customer_id AND d.created_at<=NEW.created_at)) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.reassessments') j WHERE NOT EXISTS(SELECT 1 FROM training_reassessments a JOIN training_reassessment_events e ON e.reassessment_id=a.id WHERE a.id=json_extract(j.value,'$.id') AND a.customer_id=NEW.customer_id AND a.store_id=NEW.store_id AND e.version=json_extract(j.value,'$.version') AND e.revision=json_extract(j.value,'$.revision') AND e.status='checked' AND e.created_at<=NEW.created_at)) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.observations') j WHERE NOT EXISTS(SELECT 1 FROM longitudinal_observation_versions v WHERE v.observation_id=json_extract(j.value,'$.id') AND v.version=json_extract(j.value,'$.version') AND v.case_id=NEW.case_id AND v.store_id=NEW.store_id AND v.customer_id=NEW.customer_id AND v.sequence<=NEW.base_sequence AND v.version=(SELECT max(version) FROM longitudinal_observation_versions WHERE observation_id=v.observation_id AND sequence<=NEW.base_sequence) AND v.created_at<=NEW.created_at)) OR(json_type(NEW.manifest_json,'$.followup')='object' AND NOT EXISTS(SELECT 1 FROM work_tasks t JOIN longitudinal_cases c ON c.id=NEW.case_id JOIN task_events e ON e.task_id=t.id AND e.revision=t.revision WHERE t.id=json_extract(NEW.manifest_json,'$.followup.id') AND t.revision=json_extract(NEW.manifest_json,'$.followup.revision') AND t.customer_id=NEW.customer_id AND t.store_id=NEW.store_id AND t.cycle_id=c.cycle_id AND e.created_at<=NEW.created_at)) BEGIN SELECT RAISE(ABORT,'longitudinal manifest source mismatch'); END;

CREATE TRIGGER longitudinal_case_versions_actionable_task BEFORE INSERT ON longitudinal_case_versions WHEN json_type(NEW.manifest_json,'$.followup')='object' AND EXISTS(SELECT 1 FROM work_tasks t WHERE t.id=json_extract(NEW.manifest_json,'$.followup.id') AND (t.lifecycle_status!='active' OR EXISTS(SELECT 1 FROM task_completions WHERE task_id=t.id))) BEGIN SELECT RAISE(ABORT,'longitudinal next task already ended'); END;

CREATE TRIGGER longitudinal_observation_versions_manifest_shape BEFORE INSERT ON longitudinal_observation_versions WHEN json_type(NEW.manifest_json) IS NOT 'object' OR (SELECT count(*) FROM json_each(NEW.manifest_json))!=4 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json) WHERE key NOT IN('documents','reassessments','observations','followup')) OR json_type(NEW.manifest_json,'$.observations') IS NOT 'array' OR json_array_length(NEW.manifest_json,'$.observations')>30 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.observations') j WHERE j.type!='object' OR (SELECT count(*) FROM json_each(j.value))!=2 OR json_type(j.value,'$.id') IS NOT 'text' OR length(json_extract(j.value,'$.id')) NOT BETWEEN 1 AND 100 OR EXISTS(SELECT 1 FROM json_each(j.value) WHERE key NOT IN('id','version')) OR json_type(j.value,'$.version') IS NOT 'integer' OR json_extract(j.value,'$.version') NOT BETWEEN 1 AND 1000000000) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.observations') GROUP BY json_extract(value,'$.id') HAVING count(*)>1) OR json_type(NEW.manifest_json,'$.reassessments') IS NOT 'array' OR json_array_length(NEW.manifest_json,'$.reassessments')>30 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.reassessments') j WHERE j.type!='object' OR (SELECT count(*) FROM json_each(j.value))!=3 OR json_type(j.value,'$.id') IS NOT 'text' OR length(json_extract(j.value,'$.id')) NOT BETWEEN 1 AND 100 OR EXISTS(SELECT 1 FROM json_each(j.value) WHERE key NOT IN('id','version','revision')) OR json_type(j.value,'$.version') IS NOT 'integer' OR json_extract(j.value,'$.version') NOT BETWEEN 1 AND 1000000000 OR json_type(j.value,'$.revision') IS NOT 'integer' OR json_extract(j.value,'$.revision') NOT BETWEEN 1 AND 1000000000) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.reassessments') GROUP BY json_extract(value,'$.id') HAVING count(*)>1) OR json_type(NEW.manifest_json,'$.documents') IS NOT 'array' OR json_array_length(NEW.manifest_json,'$.documents')>30 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.documents') WHERE type!='text' OR length(value) NOT BETWEEN 1 AND 100) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.documents') GROUP BY value HAVING count(*)>1) OR json_type(NEW.manifest_json,'$.followup') IS NULL OR json_type(NEW.manifest_json,'$.followup') NOT IN('null','object') OR(json_type(NEW.manifest_json,'$.followup')='object' AND ((SELECT count(*) FROM json_each(NEW.manifest_json,'$.followup'))!=2 OR json_type(NEW.manifest_json,'$.followup.id') IS NOT 'text' OR length(json_extract(NEW.manifest_json,'$.followup.id')) NOT BETWEEN 1 AND 100 OR json_type(NEW.manifest_json,'$.followup.revision') IS NOT 'integer' OR json_extract(NEW.manifest_json,'$.followup.revision') NOT BETWEEN 1 AND 1000000000 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.followup') WHERE key NOT IN('id','revision')))) OR json_type(NEW.manifest_json,'$.followup') IS NOT 'null' OR json_array_length(NEW.manifest_json,'$.observations')!=0 BEGIN SELECT RAISE(ABORT,'longitudinal manifest shape mismatch'); END;

