t_json,'$.documents') WHERE type!='text' OR length(value) NOT BETWEEN 1 AND 100) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.documents') GROUP BY value HAVING count(*)>1) OR json_type(NEW.manifest_json,'$.followup') IS NULL OR json_type(NEW.manifest_json,'$.followup') NOT IN('null','object') OR(json_type(NEW.manifest_json,'$.followup')='object' AND ((SELECT count(*) FROM json_each(NEW.manifest_json,'$.followup'))!=2 OR json_type(NEW.manifest_json,'$.followup.id') IS NOT 'text' OR length(json_extract(NEW.manifest_json,'$.followup.id')) NOT BETWEEN 1 AND 100 OR json_type(NEW.manifest_json,'$.followup.revision') IS NOT 'integer' OR json_extract(NEW.manifest_json,'$.followup.revision') NOT BETWEEN 1 AND 1000000000 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.followup') WHERE key NOT IN('id','revision')))) BEGIN SELECT RAISE(ABORT,'longitudinal manifest shape mismatch'); END;

CREATE TRIGGER review_plan_events_manifest_source BEFORE INSERT ON review_plan_events WHEN NEW.action IN('create','revise','resume','complete') AND (EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.documents') j WHERE NOT EXISTS(SELECT 1 FROM document_versions d WHERE d.id=j.value AND d.customer_id=NEW.customer_id AND d.created_at<=NEW.created_at)) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.reassessments') j WHERE NOT EXISTS(SELECT 1 FROM training_reassessments a JOIN training_reassessment_events e ON e.reassessment_id=a.id WHERE a.id=json_extract(j.value,'$.id') AND a.customer_id=NEW.customer_id AND a.store_id=NEW.store_id AND e.version=json_extract(j.value,'$.version') AND e.revision=json_extract(j.value,'$.revision') AND e.status='checked' AND e.created_at<=NEW.created_at)) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.observations') j WHERE NOT EXISTS(SELECT 1 FROM longitudinal_observation_versions v WHERE v.observation_id=json_extract(j.value,'$.id') AND v.version=json_extract(j.value,'$.version') AND v.case_id=NEW.case_id AND v.store_id=NEW.store_id AND v.customer_id=NEW.customer_id AND v.sequence<=NEW.sequence-1 AND v.version=(SELECT max(version) FROM longitudinal_observation_versions WHERE observation_id=v.observation_id AND sequence<=NEW.sequence-1) AND v.created_at<=NEW.created_at)) OR(json_type(NEW.manifest_json,'$.followup')='object' AND NOT EXISTS(SELECT 1 FROM work_tasks t JOIN longitudinal_cases c ON c.id=NEW.case_id JOIN task_events e ON e.task_id=t.id AND e.revision=t.revision WHERE t.id=json_extract(NEW.manifest_json,'$.followup.id') AND t.revision=json_extract(NEW.manifest_json,'$.followup.revision') AND t.customer_id=NEW.customer_id AND t.store_id=NEW.store_id AND t.cycle_id=c.cycle_id AND e.created_at<=NEW.created_at))) OR(NEW.action='cancel' AND json_type(NEW.manifest_json,'$.followup')='object' AND NOT EXISTS(SELECT 1 FROM work_tasks t JOIN longitudinal_cases c ON c.id=NEW.case_id WHERE t.id=json_extract(NEW.manifest_json,'$.followup.id') AND t.revision=json_extract(NEW.manifest_json,'$.followup.revision') AND t.customer_id=NEW.customer_id AND t.store_id=NEW.store_id AND t.cycle_id=c.cycle_id)) BEGIN SELECT RAISE(ABORT,'longitudinal manifest source mismatch'); END;

CREATE TRIGGER review_plan_events_actionable_task BEFORE INSERT ON review_plan_events WHEN json_type(NEW.manifest_json,'$.followup')='object' AND NEW.action IN('cancel','complete') AND EXISTS(SELECT 1 FROM work_tasks t WHERE t.id=json_extract(NEW.manifest_json,'$.followup.id') AND (t.lifecycle_status!='active' OR EXISTS(SELECT 1 FROM task_completions WHERE task_id=t.id))) BEGIN SELECT RAISE(ABORT,'longitudinal next task already ended'); END;

CREATE TRIGGER longitudinal_case_activation_source BEFORE INSERT ON longitudinal_case_events WHEN NEW.action IN('activate','resume') AND EXISTS(SELECT 1 FROM longitudinal_case_versions v WHERE v.case_id=NEW.case_id AND v.version=NEW.version AND (EXISTS(SELECT 1 FROM json_each(v.manifest_json,'$.documents') j WHERE NOT EXISTS(SELECT 1 FROM document_versions d WHERE d.id=j.value AND d.customer_id=NEW.customer_id AND d.created_at<=NEW.created_at)) OR EXISTS(SELECT 1 FROM json_each(v.manifest_json,'$.reassessments') j WHERE NOT EXISTS(SELECT 1 FROM training_reassessments a JOIN training_reassessment_events e ON e.reassessment_id=a.id WHERE a.id=json_extract(j.value,'$.id') AND a.customer_id=NEW.customer_id AND a.store_id=NEW.store_id AND e.version=json_extract(j.value,'$.version') AND e.revision=json_extract(j.value,'$.revision') AND e.status='checked' AND e.created_at<=NEW.created_at)) OR EXISTS(SELECT 1 FROM json_each(v.manifest_json,'$.observations') j WHERE NOT EXISTS(SELECT 1 FROM longitudinal_observation_versions v WHERE v.observation_id=json_extract(j.value,'$.id') AND v.version=json_extract(j.value,'$.version') AND v.case_id=NEW.case_id AND v.store_id=NEW.store_id AND v.customer_id=NEW.customer_id AND v.sequence<=NEW.sequence-1 AND v.version=(SELECT max(version) FROM longitudinal_observation_versions WHERE observation_id=v.observation_id AND sequence<=NEW.sequence-1) AND v.created_at<=NEW.created_at)) OR(json_type(v.manifest_json,'$.followup')='object' AND NOT EXISTS(SELECT 1 FROM work_tasks t JOIN longitudinal_cases c ON c.id=NEW.case_id JOIN task_events e ON e.task_id=t.id AND e.revision=t.revision WHERE t.id=json_extract(v.manifest_json,'$.followup.id') AND t.revision=json_extract(v.manifest_json,'$.followup.revision') AND t.customer_id=NEW.customer_id AND t.store_id=NEW.store_id AND t.cycle_id=c.cycle_id AND e.created_at<=NEW.created_at)))) BEGIN SELECT RAISE(ABORT,'longitudinal current dossier source mismatch'); END;

CREATE TRIGGER review_plan_cancel_fixed_sources BEFORE INSERT ON review_plan_events WHEN NEW.action='cancel' AND EXISTS(SELECT 1 FROM review_plan_current p WHERE p.plan_id=NEW.plan_id AND json_remove(NEW.manifest_json,'$.followup')!=json_remove(p.manifest_json,'$.followup')) BEGIN SELECT RAISE(ABORT,'review plan fixed cancellation sources'); END;
CREATE TRIGGER longitudinal_case_close_task_time BEFORE INSERT ON longitudinal_case_events WHEN NEW.followup_task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM task_events e WHERE e.task_id=NEW.followup_task_id AND e.revision=NEW.followup_revision AND e.created_at<=NEW.created_at) BEGIN SELECT RAISE(ABORT,'longitudinal future next task'); END;
CREATE TRIGGER review_plan_cancel_task_time BEFORE INSERT ON review_plan_events WHEN NEW.action='cancel' AND json_type(NEW.manifest_json,'$.followup')='object' AND NOT EXISTS(SELECT 1 FROM task_events e WHERE e.task_id=json_extract(NEW.manifest_json,'$.followup.id') AND e.revision=json_extract(NEW.manifest_json,'$.followup.revision') AND e.created_at<=NEW.created_at) BEGIN SELECT RAISE(ABORT,'longitudinal future next task'); END;
